/**
 * Round a dollar amount to whole cents, half away from zero.
 *
 * Scaling by 100 carries over the binary representation error of the input
 * (1.005 * 100 is 100.49999999999999) and adding many fractional lines piles
 * up more of it, so the scaled value is first collapsed to 15 significant
 * digits: short enough to drop that noise, long enough to keep every cent a
 * realistic invoice can hold distinct. Rounding the magnitude keeps credits
 * symmetric with charges, unlike Math.round, which rounds -0.5 towards zero.
 */
function roundToCents(dollars: number): number {
  const cents = Number((dollars * 100).toPrecision(15))
  return (Math.sign(cents) * Math.round(Math.abs(cents))) / 100
}

/** The invoice total, in dollars, rounded to cents. */
export function invoiceTotal(items: readonly LineItem[]): number {
  const raw = items.reduce((sum, item) => sum + lineTotal(item), 0)
  return roundToCents(raw)
}

const cents = Number((dollars * 100).toPrecision(15))
const rounded = Math.sign(cents) * Math.round(Math.abs(cents))
// Guard against handing back the -0 that a sub-half-cent credit produces.
