/**
 * Round a dollar amount to whole cents, half away from zero.
 *
 * Binary floating point stores 1.005 a hair below the decimal value it prints
 * as, and summing many fractional lines piles up more of that error, so the
 * scaled amount can land just under a half-cent boundary it was meant to sit
 * on (1.005 * 100 is 100.49999999999999). Nudging by a tolerance relative to
 * the amount clears that noise; the quarter-cent cap keeps the nudge from
 * moving anything that was not already on the boundary. Rounding the
 * magnitude keeps credits symmetric with charges, unlike Math.round, which
 * pushes -0.5 towards zero.
 */
function roundToCents(dollars: number): number {
  const cents = Math.abs(dollars) * 100
  const tolerance = Math.min(cents * 1e-9, 0.25)
  const rounded = Math.round(cents + tolerance) * Math.sign(dollars)
  // Guard against handing back the -0 a sub-half-cent credit would produce.
  return rounded === 0 ? 0 : rounded / 100
}

